-- Run in the Supabase SQL editor. Never put the service-role key in this app.
create extension if not exists pgcrypto;
create table public.admin_profiles (id uuid primary key references auth.users(id) on delete cascade, created_at timestamptz not null default now());
create table public.codes (id uuid primary key default gen_random_uuid(), title text not null check (char_length(title) between 1 and 160), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.code_lines (id uuid primary key default gen_random_uuid(), code_id uuid not null references public.codes(id) on delete cascade, line_text text not null, correct_position integer not null check(correct_position > 0), created_at timestamptz not null default now(), unique(code_id,correct_position));
create table public.authentication_codes (id uuid primary key default gen_random_uuid(), auth_code varchar(4) not null check(auth_code ~ '^[0-9]{4}$'), code_id uuid not null references public.codes(id) on delete restrict, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create unique index authentication_codes_active_unique on public.authentication_codes(auth_code) where is_active;
create table public.exam_attempts (id uuid primary key default gen_random_uuid(), access_token uuid not null default gen_random_uuid() unique, roll_number text not null, student_name text not null, code_id uuid not null references public.codes(id) on delete restrict, authentication_code_id uuid not null references public.authentication_codes(id) on delete restrict, started_at timestamptz not null default now(), submitted_at timestamptz, elapsed_seconds integer, correct_lines integer, total_lines integer not null, submitted_line_ids uuid[], submission_type text check(submission_type in ('manual','auto')), status text not null default 'active' check(status in ('active','completed')), created_at timestamptz not null default now());
create unique index one_attempt_per_roll on public.exam_attempts(roll_number);
create index attempts_ranking on public.exam_attempts(correct_lines desc,elapsed_seconds asc) where status='completed';
alter table public.admin_profiles enable row level security; alter table public.codes enable row level security; alter table public.code_lines enable row level security; alter table public.authentication_codes enable row level security; alter table public.exam_attempts enable row level security;
create function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from admin_profiles where id=auth.uid())$$;
create policy admin_all_codes on public.codes for all using (is_admin()) with check (is_admin());
create policy admin_all_lines on public.code_lines for all using (is_admin()) with check (is_admin());
create policy admin_all_auth on public.authentication_codes for all using (is_admin()) with check (is_admin());
create policy admin_all_attempts on public.exam_attempts for all using (is_admin()) with check (is_admin());
create policy admin_profile_self on public.admin_profiles for select using (id=auth.uid());
create or replace function public.start_exam(p_roll_number text,p_student_name text,p_auth_code text) returns uuid language plpgsql security definer set search_path=public as $$declare v_auth authentication_codes%rowtype; v_id uuid;begin if p_roll_number <> upper(regexp_replace(p_roll_number,'\\s','','g')) then raise exception 'INVALID_ROLL'; end if exists(select 1 from exam_attempts where roll_number=p_roll_number) then raise exception 'TAKEN'; end if p_student_name='' then raise exception 'INVALID_NAME'; end if p_auth_code !~ '^[0-9]{4}$' then raise exception 'AUTH'; end if select * into v_auth from authentication_codes where auth_code=p_auth_code and is_active; if not found then raise exception 'AUTH';end if insert into exam_attempts(roll_number,student_name,code_id,authentication_code_id,total_lines) values(p_roll_number,left(p_student_name,120),v_auth.code_id,v_auth.id,(select count(*) from code_lines where code_id=v_auth.code_id)) returning id into v_id; return v_id; exception when unique_violation then raise exception 'TAKEN'; end$$;
create or replace function public.get_exam_attempt(p_attempt_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare a exam_attempts%rowtype;begin select * into a from exam_attempts where id=p_attempt_id; if not found then return null;end if return jsonb_build_object('id',a.id,'roll_number',a.roll_number,'student_name',a.student_name,'started_at',a.started_at,'submitted_at',a.submitted_at,'elapsed_seconds',a.elapsed_seconds,'correct_lines',a.correct_lines,'total_lines',a.total_lines,'status',a.status,'submission_type',a.submission_type,'code_title',(select title from codes where id=a.code_id),'assigned_lines',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'line_text',line_text,'display_position',random()) order by random()),'[]'::jsonb) from code_lines where code_id=a.code_id));end$$;
create or replace function public.submit_exam(p_attempt_id uuid,p_line_ids uuid[],p_submission_type text default 'manual') returns void language plpgsql security definer set search_path=public as $$declare a exam_attempts%rowtype; v_correct integer;begin select * into a from exam_attempts where id=p_attempt_id for update; if not found then raise exception 'NOT_FOUND';end if if a.status<>'active' then raise exception 'ALREADY_SUBMITTED';end if if cardinality(p_line_ids)<>a.total_lines or exists(select 1 from unnest(p_line_ids) x group by x having count(*)>1) or exists(select 1 from unnest(p_line_ids) x where x not in(select id from code_lines where code_id=a.code_id)) then raise exception 'INVALID_SUBMISSION';end if select count(*) into v_correct from (select u.ord,c.line_text from unnest(p_line_ids) with ordinality u(id,ord) join code_lines c on c.id=u.id) s join code_lines expected on expected.code_id=a.code_id and expected.correct_position=s.ord and expected.line_text=s.line_text; update exam_attempts set submitted_at=now(),elapsed_seconds=greatest(0,extract(epoch from now()-started_at)::int),correct_lines=v_correct,submitted_line_ids=p_line_ids,submission_type=case when p_submission_type='auto' then 'auto' else 'manual' end,status='completed' where id=a.id;end$$;
create or replace function public.admin_create_code(p_title text,p_lines text[]) returns uuid language plpgsql security definer set search_path=public as $$declare v_id uuid;begin if not is_admin() then raise exception 'FORBIDDEN';end if cardinality(p_lines)<1 then raise exception 'EMPTY';end if insert into codes(title) values(p_title) returning id into v_id;insert into code_lines(code_id,line_text,correct_position) select v_id,line_text,ord::int from unnest(p_lines) with ordinality as x(line_text,ord);return v_id;end$$;
create or replace view public.ranked_results with (security_invoker=true) as select a.id,a.roll_number,a.student_name,a.elapsed_seconds,a.correct_lines,a.total_lines,a.status,a.submission_type,c.title as code_title from exam_attempts a join codes c on c.id=a.code_id where a.status='completed' order by a.correct_lines desc,a.elapsed_seconds asc,a.submitted_at asc;
grant execute on function public.start_exam(text,text,text),public.get_exam_attempt(uuid),public.submit_exam(uuid,uuid[],text) to anon,authenticated; grant execute on function public.admin_create_code(text,text[]) to authenticated;
-- After creating an Auth user as an administrator, add its UUID: insert into public.admin_profiles(id) values ('AUTH_USER_UUID');
